"""
Simple Bank Ledger

This module implements a simple bank ledger system supporting accounts, transfers with overdraft rules, interest accrual, monthly statements, and CSV export.
"""

import csv
import json
import os
from datetime import datetime, timedelta

class Account:
    """Represents a bank account with balance and transaction history."""
    def __init__(self, account_id, owner, balance=0.0):
        self.account_id = account_id
        self.owner = owner
        self.balance = balance
        self.transactions = []  # (date, amount, description)

    def deposit(self, amount, date=None, description="Deposit"):
        date = date or datetime.now()
        self.balance += amount
        self.transactions.append((date, amount, description))

    def withdraw(self, amount, date=None, description="Withdrawal"):
        date = date or datetime.now()
        self.balance -= amount
        self.transactions.append((date, -amount, description))

    def get_monthly_statement(self, year, month):
        statement = []
        for (date, amount, description) in self.transactions:
            if date.year == year and date.month == month:
                statement.append((date, amount, description))
        return statement

    def to_csv(self, year, month, filepath):
        statement = self.get_monthly_statement(year, month)
        with open(filepath, 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(['Date', 'Amount', 'Description'])
            for (date, amount, description) in statement:
                writer.writerow([date.strftime('%Y-%m-%d'), amount, description])

class Ledger:
    """Bank Ledger to manage multiple accounts, transfers, overdraft rules, interest, and statements."""
    def __init__(self, config_path='config.json'):
        if os.path.exists(config_path):
            with open(config_path) as f:
                self.config = json.load(f)
        else:
            self.config = {}
        self.accounts = {}

    def create_account(self, account_id, owner, balance=0.0):
        if account_id in self.accounts:
            raise ValueError('Account already exists')
        self.accounts[account_id] = Account(account_id, owner, balance)

    def transfer(self, from_id, to_id, amount, date=None):
        date = date or datetime.now()
        from_acc = self.accounts.get(from_id)
        to_acc = self.accounts.get(to_id)
        if not from_acc or not to_acc:
            raise ValueError('Invalid account')
        # enforce overdraft limits
        overdraft_limit = self.config.get('overdraft_limit', {}).get(from_id, 0)
        if from_acc.balance - amount < -overdraft_limit:
            raise ValueError('Overdraft limit exceeded')
        from_acc.withdraw(amount, date, f'Transfer to {to_id}')
        to_acc.deposit(amount, date, f'Transfer from {from_id}')

    def accrue_interest(self, date=None):
        date = date or datetime.now()
        for account in self.accounts.values():
            tier_interest = self.get_interest_rate(account.balance)
            interest_amount = account.balance * tier_interest / 100 / 12  # monthly interest
            if interest_amount != 0:
                account.deposit(interest_amount, date, 'Interest Accrual')

    def get_interest_rate(self, balance):
        tiers = self.config.get('interest_tiers', [])
        applicable_rate = 0.0
        for tier in tiers:
            if balance >= tier['min_balance']:
                applicable_rate = tier['rate']
            else:
                break
        return applicable_rate

    def monthly_statements(self, year, month):
        statements = {}
        for account_id, account in self.accounts.items():
            statements[account_id] = account.get_monthly_statement(year, month)
        return statements

    def export_statements_csv(self, year, month, directory='./statements'):
        os.makedirs(directory, exist_ok=True)
        for account in self.accounts.values():
            filename = f'{directory}/{account.account_id}_{year}_{month}.csv'
            account.to_csv(year, month, filename)


if __name__ == '__main__':
    ledger = Ledger('config.json')
    ledger.create_account('A001', 'Alice', 1000.0)
    ledger.create_account('B001', 'Bob', 500.0)
    ledger.transfer('A001', 'B001', 200.0)
    ledger.accrue_interest()
    ledger.export_statements_csv(datetime.now().year, datetime.now().month)
    print('Demo complete: Statements exported.')
